// Form gÃ¶nderildi
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    csrf_required();

    if (!rate_limit('contact:' . client_ip(), 5, 600)) {
        flash_set('error', 'Ã‡ok sÄ±k gÃ¶nderim. LÃ¼tfen 10 dakika sonra tekrar deneyin.');
        header('Location: /iletisim.php#form'); exit;
    }

    $first   = clean_multi($_POST['fname'] ?? '');
    $last    = clean_multi($_POST['lname'] ?? '');
    $email   = clean_multi($_POST['email'] ?? '');
    $phone   = clean_multi($_POST['phone'] ?? '');
    $branch  = (int)($_POST['branch'] ?? 0);
    $subject = clean_multi($_POST['subject'] ?? '');
    $msg     = clean_multi($_POST['msg'] ?? '');
    $rating  = isset($_POST['rating']) ? max(1, min(5, (int)$_POST['rating'])) : null;

    $errors = [];
    if (mb_strlen($first) < 2)  $errors[] = 'Ad en az 2 karakter olmalÄ±.';
    if (mb_strlen($last) < 2)   $errors[] = 'Soyad en az 2 karakter olmalÄ±.';
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) $errors[] = 'GeÃ§erli bir e-posta giriniz.';
    if (mb_strlen($subject) < 3) $errors[] = 'Konu zorunludur.';
    if (mb_strlen($msg) < 10)    $errors[] = 'Mesaj en az 10 karakter olmalÄ±.';

    if ($errors) {
        flash_set('error', implode(' ', $errors));
    } else {
        $stmt = db()->prepare(
            "INSERT INTO contact_messages (first_name,last_name,email,phone,branch_id,subject,message,rating,ip)
             VALUES (?,?,?,?,?,?,?,?,?)"
        );
        $stmt->execute([
            $first, $last, $email, $phone ?: null,
            $branch ?: null, $subject, $msg, $rating, client_ip()
        ]);

        $branchTitle = '';
        if ($branch) {
            $branchStmt = db()->prepare("SELECT title FROM branches WHERE id = ?");
            $branchStmt->execute([$branch]);
            $branchTitle = (string)($branchStmt->fetchColumn() ?: '');
        }

        $to = form_notification_email();
        if ($to) {
            $body = "<h2>Yeni Ä°letiÅŸim Formu MesajÄ±</h2>"
                  . form_mail_table([
                      'Ad' => $first,
                      'Soyad' => $last,
                      'Ad Soyad' => trim($first . ' ' . $last),
                      'E-posta' => $email,
                      'Telefon' => $phone,
                      'Åžube' => $branchTitle ?: ($branch ? 'ID: ' . $branch : ''),
                      'Konu' => $subject,
                      'Puan' => $rating ? $rating . ' / 5' : '',
                      'Mesaj' => $msg,
                      'IP' => client_ip(),
                      'Tarih' => date('d.m.Y H:i'),
                  ]);
            if (!send_mail($to, 'Ä°letiÅŸim Formu: ' . $subject, $body, $email)) {
                log_activity('mail_failed', null, 'Ä°letiÅŸim formu bildirimi gÃ¶nderilemedi: ' . $to);
            }
        }

        flash_set('success', 'MesajÄ±nÄ±z iletildi. En kÄ±sa sÃ¼rede dÃ¶nÃ¼ÅŸ yapacaÄŸÄ±z.');
        header('Location: /iletisim.php?ok=1#form'); exit;
    }
}

